fn parse_and_execute(args: Vec<String>) {
    // args[0] is program name
    let mut i = 1;
    let mut repo_path: Option<String> = None;
    let mut repo_opt: Option<String> = None;
    let mut langs_opt: Option<String> = None;
    let mut command: Option<String> = None;
    // For storing extra args for subcommands
    let mut remaining: Vec<String> = Vec::new();

    // First, handle help/version early for no args?
    // We'll parse iteratively
    let mut positional: Vec<String> = Vec::new();

    while i < args.len() {
        let arg = &args[i];
        if arg == "--help" || arg == "-h" {
            // Check context: if we are inside subcommand parsing later, but for top level:
            // If no command yet and not inside subcommand, print long_help if --help else short? Actually --help prints long, -h prints short for top level.
            // For subcommands, --help and -h both print subcommand help.
            // We need to determine if we have a command already.
            if command.is_none() && repo_opt.is_none() && langs_opt.is_none() && positional.is_empty() {
                // top level help
                if arg == "--help" {
                    print_long_help();
                } else {
                    print_short_help();
                }
                std::process::exit(0);
            } else {
                // This is help for subcommand; we'll delegate after parsing command
                remaining.push(arg.clone());
                i += 1;
                continue;
            }
        } else if arg == "--version" || arg == "-V" {
            println!("gittype 0.8.0");
            std::process::exit(0);
        } else if arg == "--repo" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--repo <REPO>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            repo_opt = Some(args[i+1].clone());
            i += 2;
            continue;
        } else if arg.starts_with("--repo=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            if val.is_empty() {
                eprintln!("error: a value is required for '--repo <REPO>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            repo_opt = Some(val);
            i += 1;
            continue;
        } else if arg == "--langs" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--langs <LANGS>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            langs_opt = Some(args[i+1].clone());
            i += 2;
            continue;
        } else if arg.starts_with("--langs=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            if val.is_empty() {
                eprintln!("error: a value is required for '--langs <LANGS>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            langs_opt = Some(val);
            i += 1;
            continue;
        } else if arg.starts_with("-") && arg.len() > 1 {
            // Unknown flag
            if arg == "--help" || arg == "-h" {
                // handled above
            } else {
                eprintln!("error: unexpected argument '{}' found", arg);
                eprintln!();
                eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
                eprintln!();
                eprintln!("Usage: executable [OPTIONS] [REPO_PATH] [COMMAND]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            i += 1;
            continue;
        } else {
            // positional
            positional.push(arg.clone());
            i += 1;
        }
    }

    // Now positional[0] could be repo_path or command
    // Commands are: history, stats, export, cache, repo, trending, help
    let commands = ["history","stats","export","cache","repo","trending","help"];
    let mut cmd_idx: Option<usize> = None;
    let mut cmd_name: Option<String> = None;
    let mut repo_path_arg: Option<String> = None;

    for (idx, pos) in positional.iter().enumerate() {
        if commands.contains(&pos.as_str()) {
            cmd_idx = Some(idx);
            cmd_name = Some(pos.clone());
            break;
        }
    }

    if let Some(idx) = cmd_idx {
        if idx == 0 {
            command = cmd_name.clone();
            // remaining positional after command
            let after: Vec<String> = positional[idx+1..].to_vec();
            remaining.extend(after);
        } else {
            // idx == 1 maybe, then first positional is repo_path, second is command? But our positional split above lumps all positionals.
            // For case: "./executable /some/path cache stats" -> positional = ["/some/path","cache","stats"] -> cmd_idx=1, command=cache, repo_path="/some/path", remaining=["stats"]
            // For "./executable history" -> positional=["history"] -> idx0
            // For "./executable /nonexistent/path" -> positional=["/nonexistent/path"] -> no command, so repo_path = that
            repo_path_arg = Some(positional[0].clone());
            command = cmd_name.clone();
            let after: Vec<String> = positional[idx+1..].to_vec();
            remaining.extend(after);
        }
    } else {
        // No command found, all positional is repo_path if any
        if positional.len() == 1 {
            repo_path_arg = Some(positional[0].clone());
        } else if positional.len() > 1 {
            // Multiple positionals without command: treat first as repo_path, rest as error? But our earlier test showed unknown top-level arg treated as REPO_PATH and then terminal error.
            // If more than one, just take first as path
            repo_path_arg = Some(positional[0].clone());
        }
    }

    // Validate langs before handling command-specific help
    if let Some(langs_str) = &langs_opt {
        let valid : std::collections::HashSet<String> = [
            "rust","rs","typescript","ts","javascript","js",
            "python","py","ruby","rb","go","swift",
            "kotlin","kt","java","php","csharp","cs","c#","c","cpp","c++","haskell","hs","dart","scala","sc","zig","clojure","clj","cljs"
        ].iter().map(|s| s.to_string()).collect();
        let parts: Vec<&str> = langs_str.split(',').collect();
        let mut invalid = Vec::new();
        for p in parts {
            let lower = p.to_lowercase();
            if !valid.contains(&lower) {
                invalid.push(p.to_string());
            }
        }
        if !invalid.is_empty() {
            let invalid_str = invalid.join(", ");
            eprintln!("❌ Unsupported language(s): {}", invalid_str);
            eprintln!("💡 Supported languages:");
            eprintln!("   rust, rs, typescript, ts, javascript, js");
            eprintln!("   python, py, ruby, rb, go, swift");
            eprintln!("   kotlin, kt, java, php, csharp, cs");
            eprintln!("   c#, c, cpp, c++, haskell, hs");
            eprintln!("   dart, scala, sc, zig, clojure, clj");
            eprintln!("   cljs");
            std::process::exit(1);
        }
    }

    // Now dispatch based on command
    match command.as_deref() {
        Some("history") => handle_history(remaining),
        Some("stats") => handle_stats(remaining),
        Some("export") => handle_export(remaining, repo_opt, langs_opt, repo_path_arg),
        Some("cache") => handle_cache(remaining),
        Some("repo") => handle_repo(remaining),
        Some("trending") => handle_trending(remaining),
        Some("help") => handle_help(remaining),
        None => {
            // Main game path
            let all_args = std::env::args().collect::<Vec<String>>();
            if !is_terminal() {
                terminal_error(&all_args);
            } else {
                run_game_tui(repo_path_arg, repo_opt, langs_opt);
            }
        },
        Some(other) => {
            // should not happen, but treat as repo_path? Actually if command is unknown, it would have been not detected as command, so repo_path path.
            // However if user passes "./executable unknown" where unknown is not a command, our earlier logic sets repo_path_arg = Some("unknown") and command=None, so it goes to main game.
            // But for "./executable cache unknown", that is handled in handle_cache.
            // So this branch shouldn't be hit for top-level unknown.
            // For safety, treat as terminal error if not help?
            let all_args = std::env::args().collect::<Vec<String>>();
            if !is_terminal() {
                terminal_error(&all_args);
            } else {
                run_game_tui(repo_path_arg, repo_opt, langs_opt);
            }
        }
    }
}

