            let all_args = std::env::args().collect::<Vec<String>>();
            let msg = format!("Validation error: Unsupported language: {}", lang);
            write_error_log(&msg, &all_args);
            std::process::exit(1);
        }
    }
    if !is_terminal() {
        let all_args = std::env::args().collect::<Vec<String>>();
        terminal_error(&all_args);
    } else {
        // check period validation before tui? But original still shows terminal error even for invalid period, so we don't validate.
        run_trending_tui();
    }
