fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() == 2 {
        if args[1] == "--version" || args[1] == "-V" {
            println!("gittype 0.8.0");
            std::process::exit(0);
        }
        if args[1] == "--help" {
            print_long_help();
            std::process::exit(0);
        }
        if args[1] == "-h" {
            print_short_help();
            std::process::exit(0);
        }
    }
    // Check for help as single command: ./executable help
    if args.len() == 2 && args[1] == "help" {
        print_long_help();
        std::process::exit(0);
    }
    parse_and_execute(args);
}

fn parse_and_execute(args: Vec<String>) {
    // args[0] is program name
    let mut repo_opt: Option<String> = None;
    let mut langs_opt: Option<String> = None;
    let mut remaining: Vec<String> = Vec::new();
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--repo" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--repo <REPO>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            repo_opt = Some(args[i+1].clone());
            i += 2;
            continue;
        } else if arg.starts_with("--repo=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            if val.is_empty() {
                eprintln!("error: a value is required for '--repo <REPO>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            repo_opt = Some(val);
            i += 1;
            continue;
        } else if arg == "--langs" {
            if i + 1 >= args.len() {
                eprintln!("error: a value is required for '--langs <LANGS>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            langs_opt = Some(args[i+1].clone());
            i += 2;
            continue;
        } else if arg.starts_with("--langs=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            if val.is_empty() {
                eprintln!("error: a value is required for '--langs <LANGS>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            langs_opt = Some(val);
            i += 1;
            continue;
        } else if arg == "--help" || arg == "-h" {
            // Defer handling: if we have already seen a command, this is subcommand help, else top-level
            // We'll push to remaining and let handlers decide, but also handle top-level case where no command yet and remaining is empty
            // To simplify, push to remaining and handle later via dispatch
            remaining.push(arg.clone());
            i += 1;
            continue;
        } else if arg == "--version" || arg == "-V" {
            println!("gittype 0.8.0");
            std::process::exit(0);
        } else if arg.starts_with("-") {
            // Unknown flag at top level
            // Need to distinguish between global unknown and subcommand unknown
            // If we have not yet seen a command, this is global unknown
            // We should check if remaining already contains a command; if so, this unknown belongs to that command and will be handled later
            // For simplicity, if remaining is empty and no command detected yet, treat as global unknown
            // Otherwise, push to remaining for subcommand to handle
            let has_command = remaining.iter().any(|r| ["history","stats","export","cache","repo","trending","help"].contains(&r.as_str()));
            if has_command {
                remaining.push(arg.clone());
                i += 1;
                continue;
            } else {
                // Check if it's --langs or --repo already handled, so this is truly unknown
                eprintln!("error: unexpected argument '{}' found", arg);
                eprintln!();
                eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
                eprintln!();
                eprintln!("Usage: executable [OPTIONS] [REPO_PATH] [COMMAND]");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
        } else {
            remaining.push(arg.clone());
            i += 1;
        }
    }

    // Validate langs if present
    if let Some(langs_str) = &langs_opt {
        let valid : std::collections::HashSet<String> = [
            "rust","rs","typescript","ts","javascript","js",
            "python","py","ruby","rb","go","swift",
            "kotlin","kt","java","php","csharp","cs","c#","c","cpp","c++","haskell","hs","dart","scala","sc","zig","clojure","clj","cljs"
        ].iter().map(|s| s.to_string()).collect();
        let parts: Vec<&str> = langs_str.split(',').collect();
        let mut invalid = Vec::new();
        for p in parts {
            let lower = p.to_lowercase();
            if !valid.contains(&lower) {
                invalid.push(p.to_string());
            }
        }
        if !invalid.is_empty() {
            let invalid_str = invalid.join(", ");
            eprintln!("❌ Unsupported language(s): {}", invalid_str);
            eprintln!("💡 Supported languages:");
            eprintln!("   rust, rs, typescript, ts, javascript, js");
            eprintln!("   python, py, ruby, rb, go, swift");
            eprintln!("   kotlin, kt, java, php, csharp, cs");
            eprintln!("   c#, c, cpp, c++, haskell, hs");
            eprintln!("   dart, scala, sc, zig, clojure, clj");
            eprintln!("   cljs");
            std::process::exit(1);
        }
    }

    if remaining.is_empty() {
        // No command or repo path: main game
        let all_args = std::env::args().collect::<Vec<String>>();
        if !is_terminal() {
            terminal_error(&all_args);
        } else {
            run_game_tui(None, repo_opt, langs_opt);
        }
        return;
    }

    // Check for help in remaining at top level: if remaining contains --help or -h and no command, print long help
    // But we already handled top-level helps that are subcommand specific. Let's handle dispatch.

    // Identify command and repo_path
    let commands = ["history","stats","export","cache","repo","trending","help"];
    // Find first occurrence of a command in remaining
    let mut cmd_idx: Option<usize> = None;
    for (idx, r) in remaining.iter().enumerate() {
        if commands.contains(&r.as_str()) {
            cmd_idx = Some(idx);
            break;
        }
    }

    let mut command: Option<String> = None;
    let mut repo_path: Option<String> = None;
    let mut cmd_args: Vec<String> = Vec::new();

    if let Some(idx) = cmd_idx {
        command = Some(remaining[idx].clone());
        // If idx ==1 and first element is not a command, then first is repo_path
        if idx == 1 {
            repo_path = Some(remaining[0].clone());
        } else if idx > 1 {
            // More than one positional before command: treat first as repo_path, ignore rest?
            repo_path = Some(remaining[0].clone());
            // But also need to ensure extra positionals before command are not considered; original would treat unknown as repo_path and still go to game if command not found.
        }
        // cmd_args are after command
        if idx + 1 < remaining.len() {
            cmd_args = remaining[idx+1..].to_vec();
        }
        // Also include any --help that was before command? But we pushed --help into remaining, so if remaining was ["--help","history"]? That would be weird.
        // For case where remaining is ["--help"] we would not have cmd_idx, so we handle top-level help later.

        // If remaining contains `--help` or `-h` before command, we should have already handled.
        // Check for top-level help case where remaining is like ["--help"] with no command
    } else {
        // No command found
        // Check if remaining contains --help or -h handling for top level
        if remaining.iter().any(|a| a=="--help") {
            print_long_help();
            std::process::exit(0);
        }
        if remaining.iter().any(|a| a=="-h") {
            print_short_help();
            std::process::exit(0);
        }
        // Check if remaining has unknown flag that should have been caught earlier: but we already handled global unknown.
        // Now remaining is repo_path or multiple
        if remaining.len() == 1 && remaining[0].starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", remaining[0]);
            eprintln!();
            eprintln!("  tip: to pass '{}' as a value, use '-- {}'", remaining[0], remaining[0]);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] [REPO_PATH] [COMMAND]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
        repo_path = Some(remaining[0].clone());
        // If more than one remaining without command, treat as repo_path + unknown? Original for unknown top-level like "unknown" as repo_path goes to game and terminal error.
        // For multiple, just take first.
        let all_args = std::env::args().collect::<Vec<String>>();
        if !is_terminal() {
            terminal_error(&all_args);
        } else {
            run_game_tui(repo_path, repo_opt, langs_opt);
        }
        return;
    }

    // At this point we have a command
    // Check if cmd_args contains help flag, or if remaining before command had help
    // Actually we need to handle help for subcommands: if cmd_args contains --help or -h, or if the command itself was called with --help before
    // Our earlier check for top-level --help being in remaining but not as command would have been handled as no command case.

    // Also handle case where remaining was ["cache","--help"] => command=cache, cmd_args=["--help"]
    // That's handled below.

    match command.as_deref() {
        Some("history") => handle_history(cmd_args),
        Some("stats") => handle_stats(cmd_args),
        Some("export") => handle_export(cmd_args),
        Some("cache") => handle_cache(cmd_args),
        Some("repo") => handle_repo(cmd_args),
        Some("trending") => handle_trending(cmd_args),
        Some("help") => handle_help(cmd_args),
        _ => unreachable!(),
    }
}

