fn handle_export(args: Vec<String>) {
    let mut format = "json".to_string();
    let mut output: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--help" || arg == "-h" {
            print_export_help();
            std::process::exit(0);
        } else if arg == "--format" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--format <FORMAT>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            format = args[i+1].clone();
            i += 2;
            continue;
        } else if arg.starts_with("--format=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            format = val;
            i += 1;
            continue;
        } else if arg == "--output" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--output <OUTPUT>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            output = Some(args[i+1].clone());
            i += 2;
            continue;
        } else if arg.starts_with("--output=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            output = Some(val);
            i += 1;
            continue;
        } else if arg.starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("Usage: executable export [OPTIONS]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("Usage: executable export [OPTIONS]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
    eprintln!("❌ Export command is not yet implemented");
    eprintln!("💡 Requested format: {}", format);
    if let Some(out) = output {
        eprintln!("💡 Requested output: {}", out);
    }
    eprintln!("💡 This feature is planned for a future release");
    std::process::exit(1);
}
fn handle_cache(args: Vec<String>) {
    if args.is_empty() {
        // Need to check if help was requested via global? But empty means error: need subcommand
        // Actually original for `cache --help` would be args = ["--help"] and we handle below
        // For `cache` alone with no subcommand, it should show usage error
        eprintln!("Usage: executable cache <COMMAND>");
