        },
        "help" => {
            if rest.is_empty() {
                print_cache_help();
                std::process::exit(0);
            } else {
                let topic = rest[0].as_str();
                match topic {
                    "stats" => { print_cache_stats_help(); std::process::exit(0);},
                    "clear" => { print_cache_clear_help(); std::process::exit(0);},
                    "list" => { print_cache_list_help(); std::process::exit(0);},
                    _ => {
