            eprintln!("error: unrecognized subcommand '{}'", sub);
            eprintln!();
            eprintln!("Usage: executable cache <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}
fn handle_repo(args: Vec<String>) {
    if args.is_empty() {
        eprintln!("Usage: executable repo <COMMAND>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if args[0] == "--help" || args[0] == "-h" {
        print_repo_help();
        std::process::exit(0);
    }
    let sub = args[0].as_str();
    let rest = if args.len() > 1 { args[1..].to_vec() } else { Vec::new() };
    match sub {
        "list" => {
            if rest.iter().any(|a| a=="--help" || a=="-h") {
                print_repo_list_help();
                std::process::exit(0);
            }
            if !rest.is_empty() {
                eprintln!("error: unexpected argument '{}' found", rest[0]);
                eprintln!();
                eprintln!("Usage: executable repo list");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            if !is_terminal() {
                let all_args = std::env::args().collect::<Vec<String>>();
                terminal_error(&all_args);
            } else {
                run_repo_list_tui();
            }
        },
        "clear" => {
            let mut force = false;
            let mut has_help = false;
            for a in &rest {
                if a == "--force" {
                    force = true;
                } else if a == "--help" || a == "-h" {
                    has_help = true;
                } else if a.starts_with("-") {
                    eprintln!("error: unexpected argument '{}' found", a);
                    eprintln!();
                    eprintln!("Usage: executable repo clear [OPTIONS]");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                } else {
                    eprintln!("error: unexpected argument '{}' found", a);
                    eprintln!();
                    eprintln!("Usage: executable repo clear [OPTIONS]");
                    eprintln!();
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(2);
                }
            }
            if has_help {
                print_repo_clear_help();
                std::process::exit(0);
            }
            let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
            let repos_dir = home.join(".gittype/repos");
            if !repos_dir.exists() {
                println!("No cached repositories directory found.");
                std::process::exit(0);
            } else {
                let mut is_empty = true;
                if let Ok(mut entries) = std::fs::read_dir(&repos_dir) {
                    if entries.next().is_some() {
                        is_empty = false;
                    }
                }
                if is_empty {
                    println!("No cached repositories directory found.");
                    std::process::exit(0);
                }
                if force {
                    println!("No cached repositories found.");
                    std::process::exit(0);
                } else {
                    if !is_terminal() {
                        println!("No cached repositories found.");
                        std::process::exit(0);
                    } else {
                        if prompt_repo_clear() {
                            let _ = std::fs::remove_dir_all(&repos_dir);
                            println!("All cached repositories cleared.");
                        } else {
                            println!("Aborted.");
                        }
                        std::process::exit(0);
                    }
                }
            }
        },
        "play" => {
            if rest.iter().any(|a| a=="--help" || a=="-h") {
                print_repo_play_help();
                std::process::exit(0);
            }
            if !rest.is_empty() {
                eprintln!("error: unexpected argument '{}' found", rest[0]);
                eprintln!();
                eprintln!("Usage: executable repo play");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            if !is_terminal() {
                let all_args = std::env::args().collect::<Vec<String>>();
                terminal_error(&all_args);
            } else {
                run_repo_play_tui();
            }
        },
        "help" => {
            if rest.is_empty() {
                print_repo_help();
                std::process::exit(0);
            } else {
                let topic = rest[0].as_str();
                match topic {
                    "list" => { print_repo_list_help(); std::process::exit(0);},
                    "clear" => { print_repo_clear_help(); std::process::exit(0);},
                    "play" => { print_repo_play_help(); std::process::exit(0);},
                    _ => { print_repo_help(); std::process::exit(0);},
                }
            }
        },
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", sub);
            eprintln!();
            eprintln!("Usage: executable repo <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    }
}
fn handle_trending(args: Vec<String>) {
    // Check for help
    if args.len()==1 && (args[0]=="--help" || args[0]=="-h") {
        print_trending_help();
        std::process::exit(0);
    }
    if args.iter().any(|a| a=="--help" || a=="-h") && args.len()==1 {
        print_trending_help();
        std::process::exit(0);
    }
    let mut period = "daily".to_string();
    let mut language: Option<String> = None;
    let mut repo_name: Option<String> = None;
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--help" || arg == "-h" {
            print_trending_help();
            std::process::exit(0);
        } else if arg == "--period" {
            if i+1 >= args.len() {
                eprintln!("error: a value is required for '--period <PERIOD>' but none was supplied");
                eprintln!();
                eprintln!("For more information, try '--help'.");
                std::process::exit(2);
            }
            period = args[i+1].clone();
            i += 2;
            continue;
        } else if arg.starts_with("--period=") {
            let val = arg.splitn(2, '=').nth(1).unwrap_or("").to_string();
            period = val;
            i += 1;
            continue;
        } else if arg.starts_with("-") {
            eprintln!("error: unexpected argument '{}' found", arg);
            eprintln!();
            eprintln!("Usage: executable trending [OPTIONS] [LANGUAGE] [REPO_NAME]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        } else {
            positional.push(arg.clone());
            i += 1;
        }
    }
    if positional.len() >= 1 {
        language = Some(positional[0].clone());
    }
    if positional.len() >= 2 {
        repo_name = Some(positional[1].clone());
    }
    if positional.len() > 2 {
        eprintln!("error: unexpected argument '{}' found", positional[2]);
        eprintln!();
        eprintln!("Usage: executable trending [OPTIONS] [LANGUAGE] [REPO_NAME]");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }
    if let Some(lang) = language.clone() {
        let valid_trending = ["C","C#","C++","Dart","Go","Haskell","Java","JavaScript","Kotlin","PHP","Python","Ruby","Rust","Scala","Swift","TypeScript"];
        if !valid_trending.contains(&lang.as_str()) {
            eprintln!("❌ Unsupported language: '{}'", lang);
            eprintln!("📚 Supported languages: C, C#, C++, Dart, Go, Haskell, Java, JavaScript, Kotlin, PHP, Python, Ruby, Rust, Scala, Swift, TypeScript");
            let all_args = std::env::args().collect::<Vec<String>>();
            let msg = format!("Validation error: Unsupported language: {}", lang);
            write_error_log(&msg, &all_args);
            std::process::exit(1);
        }
    }
    // period not validated, just pass
    let _ = period;
    let _ = repo_name;
    if !is_terminal() {
        let all_args = std::env::args().collect::<Vec<String>>();
        terminal_error(&all_args);
    } else {
        run_trending_tui();
    }
}
fn handle_help(args: Vec<String>) {
    if args.is_empty() {
        print_long_help();
        std::process::exit(0);
    }
    let topic = args[0].as_str();
    match topic {
        "history" => { print_history_help(); std::process::exit(0);},
        "stats" => { print_stats_help(); std::process::exit(0);},
        "export" => { print_export_help(); std::process::exit(0);},
        "cache" => {
            if args.len() >=2 {
                match args[1].as_str() {
                    "stats" => { print_cache_stats_help(); std::process::exit(0);},
                    "clear" => { print_cache_clear_help(); std::process::exit(0);},
                    "list" => { print_cache_list_help(); std::process::exit(0);},
                    _ => { print_cache_help(); std::process::exit(0);},
                }
            } else {
                print_cache_help(); std::process::exit(0);
            }
        },
        "repo" => {
            if args.len() >=2 {
                match args[1].as_str() {
                    "list" => { print_repo_list_help(); std::process::exit(0);},
                    "clear" => { print_repo_clear_help(); std::process::exit(0);},
                    "play" => { print_repo_play_help(); std::process::exit(0);},
                    _ => { print_repo_help(); std::process::exit(0);},
                }
            } else {
                print_repo_help(); std::process::exit(0);
            }
        },
        "trending" => {
            print_trending_help();
            std::process::exit(0);
        },
        _ => {
            print_long_help();
            std::process::exit(0);
        }
    }
}

fn is_terminal() -> bool {
    std::io::stdout().is_terminal() && std::io::stdin().is_terminal()
}
fn write_error_log(message: &str, args: &[String]) {
    let now = chrono::Utc::now();
    let timestamp = now.format("%Y%m%d_%H%M%S").to_string();
    let current_log = format!("gittype_error_{}.log", timestamp);
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
    let log_dir = home.join(".gittype/logs");
    let _ = std::fs::create_dir_all(&log_dir);
    let gittype_log = log_dir.join(format!("gittype_{}.log", timestamp));
    let work_dir = std::env::current_dir().map(|p| p.display().to_string()).unwrap_or_else(|_| ".".to_string());
    let exec_str = args.get(0).cloned().unwrap_or_else(|| "./executable".to_string());
    let content = format!(
        "ERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: {}\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {:?}\nOS: linux\nARCH: x86_64\n",
        now.format("%Y-%m-%d %H:%M:%S"),
        message,
        exec_str,
        work_dir,
        args
    );
    let _ = std::fs::write(&current_log, &content);
    let gittype_content = format!(
        "{} [INFO] gittype::infrastructure::logging - GitType logging initialized, logs saved to: {}\n{} [ERROR] gittype::infrastructure::logging - APPLICATION ERROR:\n{}\n",
        now.format("%Y-%m-%d %H:%M:%S"),
        log_dir.display(),
        now.format("%Y-%m-%d %H:%M:%S"),
        content
    );
    let _ = std::fs::write(gittype_log, gittype_content);
    eprintln!("💾 Error details written to: {}", current_log);
    eprintln!("Error: {}", message);
}
fn terminal_error(args: &[String]) -> ! {
    let term = std::env::var("TERM").unwrap_or_default();
    let msg = if term.is_empty() {
        "Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)"
    } else {
        "Terminal error: Not running in a terminal environment. Please run in a proper terminal."
    };
    write_error_log(msg, args);
    std::process::exit(1);
}
fn prompt_repo_clear() -> bool {
    use std::io::{self, Write};
    print!("Are you sure you want to clear all cached repositories? [y/N]: ");
    let _ = io::stdout().flush();
    let mut input = String::new();
